/**
 * Stable construction/lifetime failures. Domain operations retain their own
 * canonical errors. I/O and failed startup may follow partial durable changes.
 */
sealed class ServiceRuntimeException: kotlin.Exception() {

    class InvalidOptions(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class NotReady(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class ObserverCapacity(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class Reentrant(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class Closing(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class Io(

        val `code`: kotlin.Int?
        ) : ServiceRuntimeException() {
        override val message
            get() = "code=${ `code` }"
    }

    class UnsafePath(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class UnsafePermissions(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class UnsupportedPlatform(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class Identity(

        val `error`: IdentityApiException
        ) : ServiceRuntimeException() {
        override val message
            get() = "error=${ `error` }"
    }

    class Storage(

        val `reason`: ServiceStorageFailure,

        val `detail`: kotlin.String
        ) : ServiceRuntimeException() {
        override val message
            get() = "reason=${ `reason` }, detail=${ `detail` }"
    }

    /**
     * Retained construction cause, including at most 1024 UTF-8 bytes of detail.
     * The identity admission classifier remains independent of this diagnostic.
     */
    class Attachment(

        val `reason`: ServiceAttachmentFailure,

        val `detail`: kotlin.String
        ) : ServiceRuntimeException() {
        override val message
            get() = "reason=${ `reason` }, detail=${ `detail` }"
    }

    class HostBusy(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class ConnectionsUnavailable(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class Connections(

        val `detail`: kotlin.String
        ) : ServiceRuntimeException() {
        override val message
            get() = "detail=${ `detail` }"
    }

    class ConnectionDrainUnresolved(

        val `detail`: kotlin.String
        ) : ServiceRuntimeException() {
        override val message
            get() = "detail=${ `detail` }"
    }

    class HostStart(

        val `detail`: kotlin.String
        ) : ServiceRuntimeException() {
        override val message
            get() = "detail=${ `detail` }"
    }

    /**
     * The host thread joined, but reported failed shutdown.
     */
    class HostShutdown(

        val `detail`: kotlin.String
        ) : ServiceRuntimeException() {
        override val message
            get() = "detail=${ `detail` }"
    }

    /**
     * No joined shutdown proof; resources remain retained and close is pending.
     */
    class HostOwnershipUnavailable(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class LifecyclePanicked(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }

    class StartupCancelled(
        ) : ServiceRuntimeException() {
        override val message
            get() = ""
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ServiceRuntimeException> {
        override fun lift(error_buf: RustBuffer.ByValue): ServiceRuntimeException = FfiConverterTypeServiceRuntimeError.lift(error_buf)
    }


}

